import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as a,ag as n}from"./chunks/mermaid.Bf0DxEx6.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const g=JSON.parse(`{"title":"Cindy learning map","description":"Cindy is an open-source AI agent app for desktop and phone. It puts three harnesses, Claude Code, Codex and Pi, in one workspace, so that tasks, models and skills work across devices. This page is the product overview plus a decision table: it first answers 'what do I want to do, and should I use it', then points to the tutorial and the source code walkthrough.","frontmatter":{"title":"Cindy learning map","description":"Cindy is an open-source AI agent app for desktop and phone. It puts three harnesses, Claude Code, Codex and Pi, in one workspace, so that tasks, models and skills work across devices. This page is the product overview plus a decision table: it first answers 'what do I want to do, and should I use it', then points to the tutorial and the source code walkthrough.","domain":"product","tags":["multi-agent","coding-agent","device-link"],"role":"map"},"headers":[],"relativePath":"products/cindy/index.md","filePath":"products/cindy/index.md","lastUpdated":1795592559000}`),r={name:"products/cindy/index.md"};function i(d,t,s,l,h,c){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="cindy-learning-map" tabindex="-1">Cindy learning map <a class="header-anchor" href="#cindy-learning-map" aria-label="Permalink to &quot;Cindy learning map&quot;">​</a></h1><blockquote><p><strong>The short version:</strong> Cindy is an open-source AI agent app run by 心动 (XD), built for people who already use Claude Code or Codex: it puts three agent engines in one workspace, so that the same task and the same memory carry on across several engines and several devices. <strong>If you want to use several coding agents together on one device, or pick up on your phone the work you started on the computer, read this directory.</strong> If you use only one agent and need no second device, the original tool is simpler.</p></blockquote><h2 id="audience-prerequisites-non-goals" tabindex="-1">Audience / prerequisites / non-goals <a class="header-anchor" href="#audience-prerequisites-non-goals" aria-label="Permalink to &quot;Audience / prerequisites / non-goals&quot;">​</a></h2><ul><li><strong>Who</strong>: frontend engineers who already use, or plan to use, Claude Code or Codex, and want to know whether to install Cindy and how it relates to the tools they already have.</li><li><strong>Prerequisites</strong>: it is enough to know that &quot;an agent can read files and run commands&quot;. Every term is explained the first time it appears in the <a href="./cindy.html">tutorial</a>.</li><li><strong>Non-goals</strong>: <ul><li>No teaching of Claude Code, Codex or Pi themselves; see <a href="./../claude/">Claude</a>, <a href="./../codex/">Codex</a> and <a href="./../pi-coding-agent.html">Pi</a>.</li><li>No teaching of how to self-host a Cindy backend. The README states that the backend is &quot;Not in this repo&quot;.</li><li>No coverage of procurement details for the Team and Enterprise editions; neither is open yet.</li></ul></li></ul><h2 id="product-family" tabindex="-1">Product family <a class="header-anchor" href="#product-family" aria-label="Permalink to &quot;Product family&quot;">​</a></h2><p>The &quot;Official name&quot; column is copied from the official sites, the README and the repository docs opened on 2026-11-24. Rows marked &quot;In-app&quot; have no standalone page on the official site.</p><table tabindex="0"><thead><tr><th>Official name</th><th>Official URL</th><th>On this site</th></tr></thead><tbody><tr><td>Cindy (open-source client, Apache-2.0)</td><td><a href="https://cindy.app" target="_blank" rel="noreferrer">cindy.app</a> · <a href="https://cindy.cn" target="_blank" rel="noreferrer">cindy.cn</a> · <a href="https://github.com/makecindy/cindy/releases" target="_blank" rel="noreferrer">GitHub</a></td><td>This directory: <a href="./cindy.html">tutorial</a>, <a href="./source.html">source code walkthrough</a></td></tr><tr><td>Mainland China edition / international edition</td><td><a href="https://cindy.cn/download" target="_blank" rel="noreferrer">cindy.cn/download</a> · <a href="https://cindy.app/download" target="_blank" rel="noreferrer">cindy.app/download</a></td><td><a href="./cindy.html">Install section of the tutorial</a></td></tr><tr><td>Cindy&#39;s official model service (called Cindy AI in the interface)</td><td><a href="https://cindy.cn/pricing" target="_blank" rel="noreferrer">Mainland China pricing</a> · <a href="https://cindy.app/pricing" target="_blank" rel="noreferrer">International edition pricing</a></td><td>&quot;Pricing&quot; section of the tutorial</td></tr><tr><td>Mobile (iOS, iPadOS, Android)</td><td>Download page</td><td>&quot;Connect a second computer and a phone&quot; section of the tutorial</td></tr><tr><td>Linux desktop</td><td>International edition download page · <a href="https://github.com/makecindy/cindy/blob/6fdec7fb89b955be548c3f5cc9a42d83bf174aa3/docs/linux.md" target="_blank" rel="noreferrer">Installation guide</a></td><td>&quot;Install&quot; section of the tutorial</td></tr><tr><td>Device Link</td><td>In-app</td><td>&quot;Connect a second computer and a phone&quot; section of the tutorial; source code walkthrough</td></tr><tr><td>Remote desktop</td><td>In-app (phone app)</td><td>&quot;Connect a second computer and a phone&quot; section of the tutorial</td></tr><tr><td>Agent-Net (Beta)</td><td>In-app switch, off by default</td><td>Source code walkthrough</td></tr><tr><td>Companion</td><td>In-app</td><td>&quot;Build a companion&quot; section of the tutorial</td></tr><tr><td>Automation</td><td>In-app</td><td>&quot;Set up automations&quot; section of the tutorial</td></tr><tr><td>Chat channels (Slack, Telegram, Feishu and others)</td><td>In-app</td><td>&quot;Connect chat channels&quot; section of the tutorial</td></tr><tr><td>Orca (collaboration)</td><td>In-app</td><td>&quot;Use Orca to split the work between several agents&quot; section of the tutorial; source code walkthrough</td></tr><tr><td>SkillHub</td><td>In-app</td><td>&quot;Make experience stick with memory and Skills&quot; section of the tutorial</td></tr><tr><td>Official plugin repository cindy-official-plugins</td><td><a href="https://github.com/makecindy/cindy-official-plugins" target="_blank" rel="noreferrer">GitHub</a></td><td>One row in this map: the source of the official plugins and the listing process</td></tr><tr><td>Plugin engines (cindy-dsh-plugin, cindy-antigravity-plugin, cindy-zcode-plugin)</td><td><a href="https://github.com/makecindy" target="_blank" rel="noreferrer">GitHub organization</a></td><td>One row in this map: plugins that bring DeepSeek Harness, Antigravity CLI and ZCode in as engines</td></tr><tr><td>Cindy Host (<code>cindy-host</code>)</td><td>No public page; see <code>docs/host/README.md</code> in the repository</td><td>Source code walkthrough; experimental</td></tr><tr><td>Cindy Headless</td><td>No public page; see <code>apps/cindy-headless/README.md</code> in the repository</td><td>Source code walkthrough; built for containers and evaluation</td></tr><tr><td>Team and Enterprise editions (Team &amp; Enterprise)</td><td>&quot;Waitlist&quot; on the official home page</td><td>One row in this map: the status is &quot;coming soon&quot; and &quot;contact us&quot;</td></tr><tr><td>Privacy policy, terms of service</td><td><a href="https://cindy.cn/privacy" target="_blank" rel="noreferrer">cindy.cn/privacy</a> · <a href="https://cindy.app/privacy" target="_blank" rel="noreferrer">cindy.app/privacy</a> · <a href="https://cindy.cn/terms" target="_blank" rel="noreferrer">cindy.cn/terms</a></td><td>&quot;Security and privacy essentials&quot; section of the tutorial</td></tr></tbody></table><h3 id="names-that-collide-and-common-misunderstandings" tabindex="-1">Names that collide and common misunderstandings <a class="header-anchor" href="#names-that-collide-and-common-misunderstandings" aria-label="Permalink to &quot;Names that collide and common misunderstandings&quot;">​</a></h3><ul><li><strong>Check where Cindy comes from.</strong> The repository is under the <code>makecindy</code> organization, and the only two official sites are <code>cindy.app</code> and <code>cindy.cn</code>.</li><li><strong>The Mainland China edition is not the international edition.</strong> Two official sites, two account systems. The README warns, for development: &quot;Mainland China accounts must use <code>cn</code>; international edition accounts must use <code>global</code>&quot;.</li><li><strong>A harness is not a model.</strong> The harness is the execution engine (Claude Code, Codex, Pi); the model is a separate choice on another layer.</li><li><strong>Pi is a harness, not a subscription.</strong> The official site says: &quot;Pi is a Harness. You do not need to buy another subscription.&quot;</li><li><strong>The &quot;task&quot; in the interface is the session.</strong> The official documentation switches between the Chinese word, &quot;session&quot; and &quot;task&quot;; they all refer to the same thing.</li><li><strong>Device Link is not Agent-Net.</strong> The first is the existing device-to-device connection; the second is the new version labeled Beta and turned off by default.</li><li><strong>A companion is not a subagent.</strong> A companion is a role that exists across tasks; a subagent is a one-off subtask executor inside one agent.</li><li><strong>A Skill is not a plugin.</strong> A Skill is a set of instructions; a plugin is a <code>.cindy</code> package that can bring its own UI and new tools.</li><li><strong>&quot;Skip Sign-In&quot; is not a self-hosted server.</strong> It only skips signing in to a Cindy account; the client still connects to the address of the official cloud service.</li><li><strong>The source code carries a batch of old names.</strong> Inside the repository the product is called <code>xdt-maker</code>, plugins are called Ghost, collaboration is called Orca, and environment variables are prefixed <code>XDT_</code>. Search by these names when you search the code.</li><li><strong><code>cindy-host</code> and <code>cindy-headless</code> are two different things.</strong> The first is the general-purpose background service in <code>apps/host</code>; the second is the runtime for containers and evaluation in <code>apps/cindy-headless</code>.</li><li><strong>The version numbers are easy to read backwards.</strong> The earliest Release on GitHub is called <code>v1.0.0</code> (2026-07-25), while the versions released after it are numbered <code>v0.1.x</code>. <code>v1.0.0</code> has no installers attached; its notes say it &quot;marks the open-source client source snapshot of the 1.0.0 release period&quot;. As of 2026-11-24, the latest stable release is <code>v0.1.144</code>.</li></ul><h2 id="what-problem-it-solves" tabindex="-1">What problem it solves <a class="header-anchor" href="#what-problem-it-solves" aria-label="Permalink to &quot;What problem it solves&quot;">​</a></h2><p>The README describes the problem in one sentence: &quot;Connect your computers and phone, bring the models and subscriptions you already use&quot;. In daily work, it comes down to these recurring friction points:</p><table tabindex="0"><thead><tr><th>Scenario</th><th>Without Cindy</th><th>With Cindy</th></tr></thead><tbody><tr><td>Using Claude Code and Codex at the same time</td><td>Switching to another agent means explaining the background from scratch</td><td>Switch harness inside the same task and carry on; Cindy carries the context over in a handoff text</td></tr><tr><td>You are away from the computer</td><td>The work stops on the computer</td><td>Open the same task on the phone or on another computer, continue the conversation and reach the files</td></tr><tr><td>Chat cannot handle it, and you must click through the software yourself</td><td>You have to go back to the computer</td><td>Remote desktop is built into the phone app</td></tr><tr><td>A model configured on one computer</td><td>Every other device has to be configured again</td><td>Once remote calls are allowed, other devices can borrow it</td></tr><tr><td>Working methods you have built up</td><td>Scattered across each tool&#39;s own configuration</td><td>Memory, Skills and companions are managed by Cindy in one place and shared across engines</td></tr><tr><td>Repetitive work</td><td>Started by hand every time</td><td>Make it an automation, or send one @-mention in a chat channel</td></tr><tr><td>One agent cannot keep up</td><td>You carry results between several tools by hand</td><td>Orca: one Lead with several Workers, each choosing its own harness and model</td></tr></tbody></table><p>There is one thing it does <strong>not</strong> do, and the official FAQ is clear about it: after the computer shuts down, the phone cannot keep a task running. Remote tasks are executed by the computer; the phone &quot;does not automatically move the work of an offline computer to the cloud to run&quot;.</p><h3 id="compared-with-the-alternatives" tabindex="-1">Compared with the alternatives <a class="header-anchor" href="#compared-with-the-alternatives" aria-label="Permalink to &quot;Compared with the alternatives&quot;">​</a></h3><p>The table below states only the facts about Cindy&#39;s side that can be verified; for the details of other products, their own pages are authoritative.</p><table tabindex="0"><thead><tr><th>Tool</th><th>What it covers</th><th>Relation to Cindy</th><th>Who it suits</th></tr></thead><tbody><tr><td>Claude Code, Codex, Pi</td><td>Each is a harness</td><td>Cindy puts all three inside; it does not replace them</td><td>People who use only one harness and need no second device: use the original tool</td></tr><tr><td><a href="./../t3code/">T3 Code</a></td><td>A multi-agent workspace of the same kind</td><td>Similar positioning; compare them item by item when choosing</td><td>People choosing between the two</td></tr><tr><td><a href="./../tailscale/">Tailscale</a>, <a href="./../uu-remote/">UU Remote</a></td><td>Remote control and networking</td><td>Cindy&#39;s Device Link connects only the Cindy devices under your account, and remote desktop is built into the phone app only; it is not a general networking tool</td><td>People who need to connect to any device or service</td></tr><tr><td><a href="./../codex/dot.html">Codex cloud agent</a></td><td>Tasks run permanently in the cloud</td><td>Cindy lets your own computer act as the server; tasks and files stay on that machine, and the computer has to be online</td><td>People who do not want to maintain an always-on computer</td></tr><tr><td>Running agents on a server you build yourself</td><td>You deploy it and maintain it yourself</td><td>The README&#39;s wording is &quot;no server rental or self-hosting setup&quot;</td><td>People who need self-hosting and can accept that the server is not open source</td></tr></tbody></table><h2 id="quick-decision-should-you-use-it-and-where-to-start" tabindex="-1">Quick decision: should you use it, and where to start <a class="header-anchor" href="#quick-decision-should-you-use-it-and-where-to-start" aria-label="Permalink to &quot;Quick decision: should you use it, and where to start&quot;">​</a></h2><table tabindex="0"><thead><tr><th>My situation</th><th>What to use</th></tr></thead><tbody><tr><td>I use only Claude Code, on only one computer</td><td>You do not need Cindy</td></tr><tr><td>I use two or more coding agents, and repeating the background each time is tedious</td><td>Use Cindy; first read &quot;Switch harness and carry on&quot; in the <a href="./cindy.html">tutorial</a></td></tr><tr><td>I am often away from the computer and want to see tasks on the phone</td><td>Use Cindy and sign in; read &quot;Connect a second computer and a phone&quot;</td></tr><tr><td>I want to operate the software on the computer from the phone</td><td>Use Cindy&#39;s remote desktop; first make sure the computer can stay online</td></tr><tr><td>The model is configured on one computer, and other devices want to borrow it</td><td>Use Cindy&#39;s model sharing; allow remote calls on that computer</td></tr><tr><td>I want to use it on one computer only and do not want the device to stay online</td><td>Use the local mode of &quot;Skip Sign-In&quot;, with your own API key</td></tr><tr><td>I do not want to configure models myself</td><td>Sign in and use Cindy&#39;s official model service, paid per usage or by the month</td></tr><tr><td>I want several agents to each handle part of a large task</td><td>Use Orca; each Worker can choose a different harness</td></tr><tr><td>I have an always-on computer and want other devices to connect back to it</td><td>Use Cindy and sign in; turn on &quot;Allow same-account devices to control this machine&quot; on the computer</td></tr><tr><td>I have a fixed daily routine of checks and reports</td><td>Use automations and push the results to a chat channel</td></tr><tr><td>I need to audit the code or change it myself</td><td>The client is Apache-2.0; read the <a href="./source.html">source code walkthrough</a></td></tr><tr><td>I need a self-hosted backend or a private deployment</td><td>Not a fit for the personal edition; for self-deploying the Enterprise edition&#39;s Gateway, the official site says &quot;contact us&quot;</td></tr></tbody></table><h2 id="how-to-read-this-directory" tabindex="-1">How to read this directory <a class="header-anchor" href="#how-to-read-this-directory" aria-label="Permalink to &quot;How to read this directory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>What you can do after reading</th><th>When to read</th></tr></thead><tbody><tr><td><a href="./cindy.html">Tutorial</a></td><td>Install Cindy, run a first task in 10 minutes, connect the phone, set the privacy switches</td><td>The first time you come across it</td></tr><tr><td><a href="./source.html">Source code walkthrough</a></td><td>Explain the data flow of one task, where Codex plugs in, the boundary of phone-to-computer control, and how Orca is implemented</td><td>When you want to audit the code or contribute, or when the tutorial does not make &quot;why is it this way&quot; clear</td></tr></tbody></table><p>Suggested order:</p><ol><li><strong>Read the tutorial first, and complete the first task as it describes.</strong> Reading the source before you have run it gets you blocked by a pile of terms.</li><li><strong>Then read &quot;Security and privacy essentials&quot; in the tutorial.</strong> It decides whether you choose sign-in or Skip Sign-In.</li><li><strong>Read the source code walkthrough last, as needed.</strong> It answers &quot;why trust it&quot;; it does not answer &quot;how do I use it&quot;.</li></ol><h2 id="official-resources" tabindex="-1">Official resources <a class="header-anchor" href="#official-resources" aria-label="Permalink to &quot;Official resources&quot;">​</a></h2><ul><li><a href="https://github.com/makecindy/cindy/blob/6fdec7fb89b955be548c3f5cc9a42d83bf174aa3/README.zh-CN.md" target="_blank" rel="noreferrer">Chinese README in the repository</a>: the official description of the features, the two running modes, privacy and telemetry; the first source for the facts.</li><li><a href="https://cindy.cn" target="_blank" rel="noreferrer">Official site</a>: positioning, the difference between Harness and model, FAQ.</li><li><a href="https://cindy.cn/download" target="_blank" rel="noreferrer">Download page</a>: system requirements for each platform.</li><li><a href="https://cindy.cn/pricing" target="_blank" rel="noreferrer">Pricing page</a>: four price tiers, the rollover rules and eight billing rules, as of 2026-11-24.</li><li><a href="https://cindy.cn/privacy" target="_blank" rel="noreferrer">Privacy policy</a>: the use of each kind of data, heartbeat and usage statistics, retention periods.</li><li><a href="https://cindy.cn/terms" target="_blank" rel="noreferrer">Terms of service</a>: where responsibility lies in bring-your-own-key mode and in official gateway mode.</li><li><a href="https://github.com/makecindy/cindy/releases" target="_blank" rel="noreferrer">GitHub Releases</a>: release notes version by version.</li><li><a href="https://github.com/makecindy/cindy-official-plugins" target="_blank" rel="noreferrer">Official plugin repository</a>: the source of the official plugins, the review criteria and the automatic listing process.</li><li><a href="https://github.com/makecindy/cindy/blob/6fdec7fb89b955be548c3f5cc9a42d83bf174aa3/SUPPORT.md" target="_blank" rel="noreferrer">Usage support</a>: where to look first when you hit a problem, and how to file an issue.</li></ul><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./cindy.html">Tutorial</a>, <a href="./source.html">source code walkthrough</a>: the other two pages in this directory.</li><li><a href="./../claude/">Claude</a>, <a href="./../codex/">Codex</a>, <a href="./../pi-coding-agent.html">Pi</a>: the three harnesses Cindy puts inside.</li><li><a href="./../t3code/">T3 Code</a>: a multi-agent workspace of the same kind.</li><li><a href="./../tailscale/">Tailscale</a>, <a href="./../uu-remote/">UU Remote</a>: remote control and networking tools.</li><li><a href="./../codex/dot.html">Codex cloud agent</a>: another approach, with tasks running permanently in the cloud.</li></ul>',26)])])}const y=e(r,[["render",i]]);export{g as __pageData,y as default};
